return [{ json: { mimeType: item.binary.data.mimeType || 'image/jpeg', base64: base64String } }];

const SUPABASE_URL = 'https://sulxmylsgaemqfgfltkv.supabase.co';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InN1bHhteWxzZ2FlbXFmZ2xmdGt2Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4OTIxNDQwMywiZXhwIjoyMTA0NzkwNDAzfQ.t1NnbFcRxvhw0fZ2y-cx95QXdRGMOBV0zomPvQlTjk8';

const item = $input.first();
const rawText = item.json.candidates[0].content.parts[0].text;
let parsed = { monto: null, fecha: null, referencia: null };
try {
  parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
} catch (e) {}

const tasa = parseFloat($('Get Tasa BCV').item.json.valor || '0');
const alicuotaData = $('Get Alicuota').all();
const alicuota = alicuotaData.length > 0 ? alicuotaData[0].json : null;
const alicuotaMonto = alicuota ? parseFloat(alicuota.monto_unidad || '0') : 0;
const montoVes = parsed.monto != null ? parseFloat(parsed.monto) : null;
const montoUsd = montoVes && tasa > 0 ? parseFloat((montoVes / tasa).toFixed(2)) : null;

const comprobanteId = $('Webhook').item.json.body.comprobante_id;
const unidadId = $('Webhook').item.json.body.unidad_id;
const alicuotaId = alicuota ? alicuota.id : null;

let estado = 'en_revision';
let mensaje = '';

if (montoVes == null || tasa === 0) {
  estado = 'en_revision';
  mensaje = 'No pudimos leer el monto del comprobante. Quedo en revision manual.';
} else if (Math.abs(montoUsd - alicuotaMonto) < 1) {
  estado = 'conciliado';
  mensaje = 'Pago conciliado. El monto coincide con tu alicuota.';
} else {
  estado = 'discrepancia';
  mensaje = 'Discrepancia de monto. Tu pago quedo en revision manual.';
}

const headers = { 'apikey': SERVICE_KEY, 'Authorization': 'Bearer ' + SERVICE_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=representation' };

// 1. Insertar pago
const pagoBody = {
  comprobante_id: comprobanteId,
  alicuota_id: alicuotaId,
  monto_extraido_ves: montoVes,
  tasa_bcv: tasa,
  monto_equivalente_usd: montoUsd,
  referencia: parsed.referencia,
  estado: estado
};
await this.helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/pagos', headers: headers, body: pagoBody, json: true });

// 2. Actualizar comprobante
await this.helpers.httpRequest({ method: 'PATCH', url: SUPABASE_URL + '/rest/v1/comprobantes?id=eq.' + comprobanteId, headers: headers, body: { estado_extraccion: estado === 'en_revision' ? 'error_lectura' : 'extraido' }, json: true });

// 3. Si conciliado, descontar saldo
if (estado === 'conciliado' && alicuotaMonto > 0) {
  const unidRes = await this.helpers.httpRequest({ method: 'GET', url: SUPABASE_URL + '/rest/v1/unidades?id=eq.' + unidadId + '&select=saldo_deudor', headers: headers, json: true });
  const saldoActual = unidRes[0]?.saldo_deudor || 0;
  const nuevoSaldo = Math.max(0, saldoActual - alicuotaMonto);
  await this.helpers.httpRequest({ method: 'PATCH', url: SUPABASE_URL + '/rest/v1/unidades?id=eq.' + unidadId, headers: headers, body: { saldo_deudor: nuevoSaldo }, json: true });
}

return [{ json: { estado: estado, monto_extraido: montoVes, monto_usd: montoUsd, alicuota_monto: alicuotaMonto, referencia: parsed.referencia, fecha: parsed.fecha, mensaje: mensaje } }];
